from tempfile import TemporaryDirectory
import sqlite3
from src.pipeline import init_database, resolve_identity

with TemporaryDirectory() as tmp:
    conn = init_database(Path('dataset'), Path(tmp) / 'northstar.db')
    counts = {table: conn.execute(f'SELECT COUNT(*) FROM {table}').fetchone()[0] for table in ('user_identities', 'user_audit_log', 'system_activity', 'deletion_rules', 'evidence_files', 'deletion_requests')}
    snapshot_tables = [row[0] for row in conn.execute("SELECT table_name FROM _northstar_snapshot_tables")]
    assert counts['deletion_requests'] == 518
    assert len(snapshot_tables) > 0
    email = conn.execute("SELECT email FROM user_identities WHERE email <> '' LIMIT 1").fetchone()[0]
    resolved = resolve_identity(email, conn)
    indexes = {row[1] for row in conn.execute('PRAGMA index_list(user_identities)')}
    assert resolved.primary_email == email.strip().lower()
    assert email.strip().lower() in resolved.emails
    assert resolved.user_ids
    assert {'idx_user_identities_user_id', 'idx_user_identities_email', 'idx_user_identities_phone'} <= indexes
    first_snapshot_count = len(snapshot_tables)
    conn.close()
    conn = init_database(Path('dataset'), Path(tmp) / 'northstar.db')
    assert conn.execute('SELECT COUNT(*) FROM _northstar_snapshot_tables').fetchone()[0] == first_snapshot_count
    conn.close()

conn = sqlite3.connect(':memory:')
conn.executescript('''
CREATE TABLE user_identities (user_id TEXT, name TEXT, email TEXT, phone TEXT, email_hash TEXT, updated_at TEXT);
CREATE TABLE user_audit_log (audit_id TEXT, user_id TEXT, event_time TEXT, field_name TEXT, old_value TEXT, new_value TEXT);
CREATE TABLE system_activity (activity_id TEXT, event_time TEXT, event_type TEXT, source_system TEXT, target_system TEXT, resource_id TEXT, reported_result TEXT, details TEXT);
INSERT INTO user_identities VALUES ('u1','Current Name','new@example.test','555-0100','stored-hash','');
INSERT INTO user_audit_log VALUES ('a1','u1','','email','old@example.test','new@example.test');
INSERT INTO user_audit_log VALUES ('a2','u1','','phone','555-0101','555-0100');
INSERT INTO user_audit_log VALUES ('a3','u1','','name','Old Name','Current Name');
INSERT INTO system_activity VALUES ('x1','','OTHER','','','linked-by-details','','record mentions u1');
INSERT INTO system_activity VALUES ('x2','','LINK_RESOURCE_IDENTITY','','','linked-by-event','','unrelated');
''')
resolved = resolve_identity(' old@example.test ', conn)
assert resolved.user_ids == {'u1'}
assert resolved.emails == {'old@example.test', 'new@example.test'}
assert resolved.phones == {'555-0100', '555-0101'}
assert resolved.names == {'Current Name', 'Old Name'}
assert 'stored-hash' in resolved.email_hashes
assert resolved.linked_resources == {'linked-by-details', 'linked-by-event'}
print('database_counts=' + str({k: v for k, v in counts.items()}))
print('sql_snapshot_tables=' + str(first_snapshot_count))
print('identity_bfs=passed; repeated_initialization=passed; indexes=passed')
